import pytest


# Staging model with source reference, column transformations, and config
stg_orders_sql = """
{{ config(materialized='view') }}

with source_data as (
    select * from {{ source('raw', 'orders') }}
),

renamed as (
    select
        id as order_id,
        user_id as customer_id,
        order_date,
        status,
        cast(amount as decimal(10, 2)) as amount

    from source_data
)

select * from renamed
"""


# Schema documentation with model descriptions, column descriptions, and tests
schema_yml = """
version: 2

sources:
  - name: raw
    description: Raw data sources
    tables:
      - name: orders
        description: Raw orders table

models:
  - name: stg_orders
    description: Cleaned and transformed orders data with column-level validation

    columns:
      - name: order_id
        description: Unique identifier for each order
        data_tests:
          - unique
          - not_null

      - name: customer_id
        description: Reference to the customer who placed the order
        data_tests:
          - not_null

      - name: order_date
        description: Date when the order was placed
        data_tests:
          - not_null

      - name: status
        description: Current status of the order (placed, shipped, completed, etc.)
        data_tests:
          - not_null

      - name: amount
        description: Order amount in decimal format, must be positive
        data_tests:
          - not_null
          - assert_positive_amounts
"""


# Custom test for positive amounts
assert_positive_amounts_sql = """
{% test assert_positive_amounts(model, column_name) %}
    select *
    from {{ model }}
    where {{ column_name }} <= 0
{% endtest %}
"""


class StagingModelsFixture:
    @pytest.fixture(scope="class")
    def models(self):
        return {
            "staging": {
                "schema.yml": schema_yml,
                "stg_orders.sql": stg_orders_sql,
            }
        }

    @pytest.fixture(scope="class")
    def tests(self):
        return {
            "generic": {
                "assert_positive_amounts.sql": assert_positive_amounts_sql,
            }
        }

    @pytest.fixture(scope="class")
    def sources(self):
        return {
            "raw": {
                "orders": [
                    {"id": 1, "user_id": 1, "order_date": "2024-01-01", "status": "placed", "amount": 100.50},
                    {"id": 2, "user_id": 2, "order_date": "2024-01-02", "status": "shipped", "amount": 250.75},
                    {"id": 3, "user_id": 1, "order_date": "2024-01-03", "status": "completed", "amount": 75.25},
                ]
            }
        }

